def _main_accent_letter(letters, segments, i):
    """Governing accent of the word: the LAST disjunctive within the same
    maqaf segment; if none, the last accent of any kind. None if none."""
    seg = _segment_of(segments, i)
    if seg is None:
        return None
    s, e = seg
    cands = [L["index"] for L in letters[s:e + 1] if L["accent_cp"] is not None]
    if not cands:
        return None
    disj = [k for k in cands if letters[k]["accent_disjunctive"]]
    return (disj[-1] if disj else cands[-1])
